INSERT INTO vocab_library_words VALUES ('7302b307-29cf-4de3-82f3-b0c22d5bce3e', 'ee517e23-38e2-4b9d-99d6-58645dee8ad2', 'quagmire', '곤경, 헤어나기 힘든 상황', '{predicament,morass}', '{solution,resolution}', 'The negotiations descended into a political quagmire with no resolution in sight.', 'The company found itself in a legal quagmire after the merger fell through.', 198, '2026-09-16 15:59:55.459795+00', 4, '정치·경제 지문에서 복잡하고 곤란한 상황을 묘사할 때 쓰이는 어휘') ON CONFLICT DO NOTHING;
INSERT INTO vocab_library_words VALUES ('8c7b5d09-9ae0-4c0c-8485-2dec9ccad9a8', 'ee517e23-38e2-4b9d-99d6-58645dee8ad2', 'tautology', '동어반복, 같은 말을 되풀이하는 논리적 결함', '{redundancy,circularity}', '{originality,distinction}', 'The critic pointed out that the argument relied on tautology rather than genuine evidence.', 'Her definition was dismissed as a tautology, explaining the term with itself.', 199, '2026-09-16 15:59:55.459795+00', 5, '논리·수사학 지문에서 논증 오류를 지적할 때 쓰이는 최상급 정밀 어휘') ON CONFLICT DO NOTHING;
